#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
	int t; cin >> t;
    while(t--)
    {
        int n; cin >> n;
        vector<ll> a(3*n+1);
        vector<ll> ps(3*n+1,0);
        for(int i = 1; i<=3*n; i++)
        {
            cin >> a[i];
        }
        
        sort(begin(a)+1,end(a));
        reverse(begin(a)+1,end(a));
        for(int i = 1; i<=3*n; i++)
        {
            ps[i] = ps[i-1] + a[i];
        }
        
        ll ans = 0;
        ll fans = 0;
        for(int i = 0; i<=n; i++)
        {
            int lo = 1, hi = n-i;
            while(hi>lo)
            {
                int m = (hi+lo+1)/2;
                if((a[i+1+(m-1)*2] + a[i+2*m]) >= 3*a[3*n-2*i-m+1])
                {
                    lo = m;
                }
                else {hi = m-1;}
            }
            if(lo == 1)
            {
                if(a[i+1]+a[i+2] >= 3*a[3*n-2*i])
                {
                    lo = 1;
                }
                else {lo = 0;}
            }
            
            // if(i == 1) {cout << lo << " ";}
          
            fans = max(fans,ans+3*(ps[3*n-2*i-lo]-ps[i])+(ps[i+2*lo]-ps[i]));
            ans += 6*(a[i+1]);
        }
        cout << fans << "\n";
    }
}
